// Model catalog (models.json, generated by tools/build_catalog.mjs).
// "quick" = the curated quick-select list with exact download sizes;
// "more"  = every other WebLLM prebuilt chat model (shown when enabled in Settings).
// Weights download straight from Hugging Face; model libraries from GitHub.

const CATALOG_URL = new URL("../models.json", import.meta.url).href;
let catalogPromise = null;

export function sizeGroup(m) {
  if (m.bytes == null) return "more";
  if (m.bytes < 1e9) return "small";
  if (m.bytes < 2.5e9) return "medium";
  return "large";
}

export const GROUP_LABELS = {
  small: "Small · under 1 GB",
  medium: "Medium · 1–2.5 GB",
  large: "Large · over 2.5 GB (desktop GPUs)",
  more: "More WebLLM models",
};

export function loadCatalog() {
  if (!catalogPromise) {
    catalogPromise = fetch(CATALOG_URL, { cache: "no-cache" })
      .catch(() => fetch(CATALOG_URL)) // offline: the service worker answers
      .then((r) => {
        if (!r.ok) throw new Error("Could not load the model list (" + r.status + ")");
        return r.json();
      })
      .then((cat) => {
        const prep = (m, quick) => {
          const modelUrl = `https://huggingface.co/${m.hfRepo}/resolve/main/`;
          return { ...m, quick, modelUrl, libUrl: m.lib, group: quick ? sizeGroup(m) : "more" };
        };
        const quick = cat.quick.map((m) => prep(m, true));
        const more = cat.more.map((m) => prep(m, false));
        return { webllm: cat.webllm, generatedAt: cat.generatedAt, quick, more, all: [...quick, ...more] };
      })
      .catch((err) => {
        catalogPromise = null;
        throw err;
      });
  }
  return catalogPromise;
}

export function findModel(catalog, id) {
  return catalog.all.find((m) => m.id === id) || null;
}

// WebLLM AppConfig: its own prebuilt list (Hugging Face URLs), with OPFS caching.
export function buildAppConfig(catalog, prebuiltAppConfig) {
  const model_list = prebuiltAppConfig.model_list.map((rec) => {
    const m = findModel(catalog, rec.model_id);
    const features = new Set(rec.required_features || []);
    if (m && m.requiresF16) features.add("shader-f16");
    return { ...rec, required_features: [...features] };
  });
  return { model_list, cacheBackend: "opfs", opfsAccessMode: "auto" };
}
